package com.rotarypumpers.meraki;
import android.content.*;import android.graphics.*;import org.json.*;import com.rotarypumpers.meraki.core.*;import java.util.*;
/** Record-only weight and scale-derived flow; no nominal pressure trace. */
final class RecordChart extends ShotChart{
 private JSONArray rows=new JSONArray();private JSONObject recipe,reference,finished;private double start=Double.NaN;private boolean liveVisible;private final Paint paint=new Paint(3);
 RecordChart(Context c){super(c);paint.setTypeface(c.getResources().getFont(R.font.space_grotesk));setContentDescription("Recorded cup weight and calculated cup flow; dashed saved favourite and shaded target time window");}
 void context(JSONObject recipe,JSONObject reference){this.recipe=recipe;this.reference=reference;invalidate();}void start(double t){start=t;finished=null;}void visibleLive(boolean show){liveVisible=show;invalidate();}
 @Override void data(JSONArray data){rows=data==null?new JSONArray():data;finished=null;invalidate();}
 @Override void shot(JSONObject s){finished=s;rows=s.optJSONArray("samples");if(rows==null)rows=new JSONArray();start=ShotInsights.bound(s,"start_bounds");invalidate();}
 protected void onDraw(Canvas c){superBackground(c);float d=getResources().getDisplayMetrics().density,l=28*d,r=getWidth()-12*d,top=19*d,base=getHeight()*(getHeight()/d<160?.42f:.60f),flowTop=base+(getHeight()/d<160?38:35)*d,flowBottom=getHeight()-20*d;if(r<=l||base<=top)return;double origin=Double.isFinite(start)?start:rows.length()>0?rows.optJSONObject(0).optDouble("uptime"):0;double stop=finished==null?Double.POSITIVE_INFINITY:ShotInsights.bound(finished,"stop_bounds"),maxTime=40,maxWeight=recipe==null?40:Math.max(40,recipe.optDouble("yield_g",36)*1.15),maxFlow=3;JSONArray actual=liveVisible?rows:new JSONArray(),ref=reference==null?new JSONArray():reference.optJSONArray("samples");if(ref==null)ref=new JSONArray();double refStart=reference==null?0:ShotInsights.bound(reference,"start_bounds"),refStop=reference==null?0:ShotInsights.bound(reference,"stop_bounds");if(actual.length()>0)maxTime=Math.max(maxTime,Math.min(stop,actual.optJSONObject(actual.length()-1).optDouble("uptime"))-origin);if(reference!=null)maxTime=Math.max(maxTime,reference.optDouble("duration_estimate_s",0));boolean window=ShotTimeWindow.enabled(recipe);double from=window?recipe.optDouble("time_s"):0,to=window?recipe.optDouble("time_max_s"):0;if(window)maxTime=Math.max(maxTime,to+3);
  paint.setStyle(Paint.Style.FILL);if(window){paint.setColor(0x263b6f3f);c.drawRect(x(from,maxTime,l,r),top,x(to,maxTime,l,r),base,paint);c.drawRect(x(from,maxTime,l,r),flowTop,x(to,maxTime,l,r),flowBottom,paint);}paint.setTextSize(10*d);paint.setColor(0xffc2c7c2);c.drawText("Weight · g",l,12*d,paint);c.drawText("Cup flow · g/s",l,flowTop-9*d,paint);
  for(int tick=0;tick<=2;tick++){float y=base-(base-top)*tick/2;paint.setColor(0xff505954);c.drawLine(l,y,r,y,paint);paint.setColor(0xffc2c7c2);c.drawText(String.format(Locale.US,"%.0f",maxWeight*tick/2),0,y,paint);}paint.setColor(0xff505954);c.drawLine(l,flowBottom,r,flowBottom,paint);
  if(recipe!=null){double target=recipe.optDouble("yield_g");paint.setColor(0xffa9c397);paint.setPathEffect(new DashPathEffect(new float[]{4*d,4*d},0));float y=(float)(base-(base-top)*target/maxWeight);c.drawLine(l,y,r,y,paint);paint.setPathEffect(null);}
  int clip=c.save();c.clipRect(l,top,r,base);line(c,ref,refStart,refStop,maxTime,maxWeight,l,r,top,base,0xffc2c7c2,true,false,reference==null?.75:ShotInsights.gapLimit(reference));line(c,actual,origin,stop,maxTime,maxWeight,l,r,top,base,0xffb59de8,false,false,finished==null?.75:ShotInsights.gapLimit(finished));c.restoreToCount(clip);clip=c.save();c.clipRect(l,flowTop,r,flowBottom);line(c,ref,refStart,refStop,maxTime,maxFlow,l,r,flowTop,flowBottom,0xffa2aca5,true,true,reference==null?.75:ShotInsights.gapLimit(reference));line(c,actual,origin,stop,maxTime,maxFlow,l,r,flowTop,flowBottom,0xff78c8bd,false,true,finished==null?.75:ShotInsights.gapLimit(finished));c.restoreToCount(clip);
  paint.setColor(0xffc2c7c2);paint.setTextSize(10*d);c.drawText("0 s",l,base+15*d,paint);String end=String.format(Locale.US,"%.0f s",maxTime);c.drawText(end,r-paint.measureText(end),base+15*d,paint);if(window){String target=String.format(Locale.US,"%.0f–%.0f s window",from,to);c.drawText(target,l+(r-l)/2-paint.measureText(target)/2,base+15*d,paint);}paint.setColor(0xffb59de8);c.drawText("This shot",l,getHeight()-3*d,paint);paint.setColor(0xffc2c7c2);String key=reference==null?"No matching favourite":"Dashed: saved favourite";c.drawText(key,r-paint.measureText(key),getHeight()-3*d,paint);
 }
 private void superBackground(Canvas c){c.drawColor(Color.TRANSPARENT);}private float x(double t,double end,float l,float r){return (float)(l+(r-l)*t/end);}
 private void line(Canvas c,JSONArray data,double origin,double stop,double time,double max,float l,float r,float top,float bottom,int color,boolean dashed,boolean flow,double gap){if(data.length()<2||!Double.isFinite(origin))return;double[] rates=flow?CupFlow.rates(data,gap):null;Path path=new Path();boolean begun=false;double previous=Double.NaN;for(int i=0;i<data.length();i++){JSONObject row=data.optJSONObject(i);if(row==null){begun=false;continue;}double t=row.optDouble("uptime"),v=flow?rates[i]:row.optDouble("weight_g");if(t<origin)continue;if(t>stop)break;if(!Double.isFinite(t)||!Double.isFinite(v)){begun=false;continue;}float px=x(t-origin,time,l,r),py=(float)(bottom-(bottom-top)*Math.max(0,v)/max);if(!begun||t-previous>gap)path.moveTo(px,py);else path.lineTo(px,py);begun=true;previous=t;}paint.setColor(color);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(2*getResources().getDisplayMetrics().density);paint.setPathEffect(dashed?new DashPathEffect(new float[]{5,5},0):null);c.drawPath(path,paint);paint.setPathEffect(null);paint.setStyle(Paint.Style.FILL);}
}
